<script setup lang="ts">defineProps<{trace:any;states:string[]}>();const markAt=(trace:any,step:number)=>(trace.constraints||[]).find((c:any)=>c.step===step)||null;const conditional=(trace:any)=>trace.constraint_mode==='conditional'&&trace.constraint_status==='satisfied';</script><template><section class="state-bands"><header><strong>{{trace.reference}} / {{trace.tokens.length}}步</strong><span>{{conditional(trace)?'无约束结果与条件结果分别显示':'完整联合MAP与单点最高态分别显示'}}</span></header><div class="band-scroll"><div class="band-table" :style="{minWidth:Math.max(500,trace.tokens.length*24+125)+'px'}"><div class="band-row"><small>步号 / 观测</small><span v-for="(token,i) in trace.tokens" :key="i" class="token-cell"><em>{{Number(i)+1}}</em>{{token}}</span></div><div class="band-row"><small>待核对隐态假设</small><span v-for="(token,i) in trace.tokens" :key="i" class="mark-cell"><template v-if="markAt(trace,Number(i)+1)">限{{markAt(trace,Number(i)+1).allowed_states.join('/')}}</template><template v-else>·</template></span></div><div class="band-row"><small>Viterbi 联合MAP</small><span v-for="(s,i) in trace.viterbi_path" :key="i" :class="['state-cell','state-'+s]" :title="states[s]">{{s}}</span></div><div class="band-row"><small>单点最高后验</small><span v-for="(s,i) in trace.marginal_path" :key="i" :class="['state-cell','state-'+s]" :title="states[s]">{{s}}</span></div><template v-if="conditional(trace)"><div class="band-row"><small>条件联合MAP</small><span v-for="(s,i) in trace.conditional_viterbi_path" :key="i" :class="['state-cell','state-'+s,'conditional-state']" :title="states[s]">{{s}}</span></div><div class="band-row"><small>条件单点最高态</small><span v-for="(s,i) in trace.conditional_marginal_path" :key="i" :class="['state-cell','state-'+s,'conditional-state']" :title="states[s]">{{s}}</span></div></template></div></div><div class="state-legend"><span v-for="(s,i) in states" :key="s"><i :class="'state-'+i"></i>{{i}} / {{s}}</span></div><p :class="{copper:!trace.marginal_path_is_legal}">{{trace.marginal_path_is_legal?'无约束边际拼接路径可行，但不等于联合MAP定义。':'无约束单点最高态拼接违反零概率约束，不能当作合法路径。'}}</p><p v-if="conditional(trace)" :class="{copper:!trace.conditional_marginal_path_is_legal}">条件结果只在满足标记的路径集合内求和、取联合MAP；{{trace.conditional_marginal_path_is_legal?'条件边际拼接仍不等于条件联合MAP。':'条件边际拼接在条件路径集合内仍违反零转移。'}}</p></section></template>
